const o=new URL("./styles.css",import.meta.url).href;export class CustomFooter extends HTMLElement{scrolledFooter=!1;constructor(){super(),this.attachShadow({mode:"open"})}render(){this.shadowRoot.innerHTML=`\n      <link rel="stylesheet" href="${o}">\n      <footer class="footer">\n        <custom-nav></custom-nav>\n\n      <div class="ctas">\n        <a href="./src/downloads/CV_Folio.pdf" class="cta">Download Folio</a>\n        <a href="mailto:hello@dallasgale.com" class="cta" onclick="gtag('event', 'click', {\n              event_category: 'outbound',\n              event_label: 'CONTACT_ME_link'\n            });">Contact Me</a>\n      </div>\n      </footer>\n    `}listenForScroll(){const o=this.shadowRoot.querySelector(".footer");window.addEventListener("scroll",()=>{window.requestAnimationFrame(()=>{const e=window.scrollY>100;o.classList.toggle("scrolled",e)})})}connectedCallback(){console.log("Custom element added to page."),this.render(),this.listenForScroll()}connectedMoveCallback(){console.log("Custom element moved with moveBefore()")}}customElements.define("custom-footer",CustomFooter);